const newListings   = $('New Listings 7d').first().json?.result?.total ?? 0;
const newEnquiries  = $('New Enquiries 7d').first().json?.result?.total ?? 0;
const activeBuyers  = $('Total Active Buyers').first().json?.result?.total ?? 0;
const underOffer    = $('Listings Under Offer').first().json?.result?.total ?? 0;
const inspections   = $('Inspections Last 7d').first().json?.result?.total ?? 0;
const listings30d   = $('Listings Over 30d').first().json?.result?.total ?? 0;

const apprRows      = $('Appraisals 7d').first().json?.result?.rows || [];
const apprSale      = apprRows.filter(a => (a.listing_category?.id || a.listing_category_id || '') === 'residential_sale').length;
const apprRental    = apprRows.filter(a => (a.listing_category?.id || a.listing_category_id || '') === 'residential_rental').length;
const apprAttended  = apprRows.filter(a => (a.appraisal_state?.id || a.appraisal_state || '') === 'archived').length;
const wonSale       = apprRows.filter(a => (a.archive_reason?.id || a.archive_reason || '') === 'won' && (a.listing_category?.id || a.listing_category_id || '') === 'residential_sale').length;
const wonRental     = apprRows.filter(a => (a.archive_reason?.id || a.archive_reason || '') === 'won' && (a.listing_category?.id || a.listing_category_id || '') === 'residential_rental').length;

const nowBris = new Date(Date.now() + 10*60*60*1000);
const dateStr = nowBris.toISOString().slice(0,10);

const DAY_NAMES   = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const MONTH_SHORT = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const dow = nowBris.getUTCDay();
const d   = nowBris.getUTCDate();
const mo  = nowBris.getUTCMonth();
const yr  = nowBris.getUTCFullYear();
const dateLabel = DAY_NAMES[dow] + ', ' + d + ' ' + MONTH_SHORT[mo] + ' ' + yr;

function pad(label, value, width) {
  const s = String(value);
  return label + ':' + ' '.repeat(Math.max(1, width - label.length)) + s;
}
const W = 30;
const summary = [
  '📊 Rex Weekly Report — ' + dateLabel,
  '─'.repeat(42),
  pad('New Listings (7d)',         newListings,  W),
  pad('New Enquiries (7d)',        newEnquiries, W),
  pad('Total Active Buyers',       activeBuyers, W),
  pad('Listings Under Offer (7d)', underOffer,   W),
  pad('Inspections Last 7d',       inspections,  W),
  pad('Appraisals Booked Sale',    apprSale,     W),
  pad('Appraisals Booked Rental',  apprRental,   W),
  pad('Appraisals Attended',       apprAttended, W),
  pad('Listings Won Sale (7d)',     wonSale,      W),
  pad('Listings Won Rental (7d)',   wonRental,    W),
  pad('Listings Over 30d',         listings30d,  W),
  '─'.repeat(42),
  'Last Updated: ' + dateStr
].join('\n');

return [{ json: {
  newListings, newEnquiries, activeBuyers, underOffer,
  inspections, apprSale, apprRental, apprAttended,
  wonSale, wonRental, listings30d, dateStr, summary
}}];

const incoming = $('Split Into Custom Values').all().map(i => i.json);
const existing = $('Get Existing Custom Values').first().json?.customValues || [];

return incoming.map(metric => {
  const match = existing.find(e => e.name === metric.name);
  return {
    json: {
      name: metric.name,
      value: metric.value,
      existingId: match?.id || null
    }
  };
});

